import React from 'react';
import { Home, Search, Heart, History, PlusCircle, Radio, User } from 'lucide-react';
import { Tab } from '../types';

interface SidebarProps {
  activeTab: Tab;
  setActiveTab: (tab: Tab) => void;
  isMobile: boolean;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isMobile }) => {
  const navItems = [
    { id: Tab.HOME, icon: Home, label: 'Trang chủ' },
    { id: Tab.SEARCH, icon: Search, label: 'Tìm kiếm' },
    { id: Tab.FAVORITES, icon: Heart, label: 'Yêu thích' },
    { id: Tab.HISTORY, icon: History, label: 'Lịch sử' },
    { id: Tab.PROFILE, icon: User, label: 'Tài khoản' },
  ];

  const sidebarClasses = isMobile 
    ? "fixed bottom-0 left-0 right-0 h-16 bg-cyber-black/90 backdrop-blur-md border-t border-cyber-red/30 flex justify-around items-center z-50 px-2"
    : "w-64 h-full bg-cyber-black border-r border-cyber-red/20 flex flex-col p-6 hidden md:flex shrink-0";

  return (
    <div className={sidebarClasses}>
      {!isMobile && (
        <div className="mb-10 flex items-center gap-3">
          {/* Logo Image Replacement */}
          <div className="w-12 h-12 relative shrink-0">
             <div className="absolute inset-0 bg-cyber-orange/20 blur-md rounded-full"></div>
             {/* Hãy thay thế src bên dưới bằng URL hình ảnh logo của bạn */}
             <img 
               src="data:image/png;base64," 
               alt="DUGMFPT Logo" 
               className="w-full h-full object-cover rounded-full drop-shadow-[0_0_8px_rgba(255,145,0,0.6)]"
             />
          </div>
          <h1 className="text-2xl font-bold tracking-wider text-transparent bg-clip-text bg-gradient-to-r from-cyber-red to-cyber-orange">
            DUGMFPT
          </h1>
        </div>
      )}

      <nav className={`flex ${isMobile ? 'flex-row w-full justify-between' : 'flex-col gap-4'}`}>
        {navItems.map((item) => (
          <button
            key={item.id}
            onClick={() => setActiveTab(item.id)}
            className={`flex items-center gap-3 p-3 rounded-lg transition-all duration-300 group
              ${activeTab === item.id 
                ? 'bg-cyber-red/10 text-cyber-red shadow-neon-red border border-cyber-red/30' 
                : 'text-gray-400 hover:text-white hover:bg-white/5'
              }
              ${isMobile ? 'flex-col gap-1 text-xs' : 'text-md'}
            `}
          >
            <item.icon className={`${isMobile ? 'w-5 h-5' : 'w-5 h-5'} ${activeTab === item.id ? 'fill-current' : ''}`} />
            <span>{item.label}</span>
          </button>
        ))}
      </nav>

      {!isMobile && (
        <div className="mt-10 border-t border-gray-800 pt-6">
          <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest mb-4">Your Library</h3>
          <ul className="space-y-3">
            <li className="flex items-center gap-3 text-gray-400 hover:text-white cursor-pointer hover:translate-x-1 transition-transform">
              <div className="w-8 h-8 bg-gray-800 rounded flex items-center justify-center text-xs text-cyber-orange border border-cyber-orange/20">JP</div>
              <span>J-Pop Hits</span>
            </li>
            <li className="flex items-center gap-3 text-gray-400 hover:text-white cursor-pointer hover:translate-x-1 transition-transform">
              <div className="w-8 h-8 bg-gradient-to-br from-cyber-red to-cyber-orange rounded flex items-center justify-center text-black font-bold text-xs">US</div>
              <span>US-UK Top 100</span>
            </li>
             <li className="flex items-center gap-3 text-gray-400 hover:text-white cursor-pointer hover:translate-x-1 transition-transform">
              <div className="w-8 h-8 bg-gray-800 rounded flex items-center justify-center text-xs text-cyber-red">
                <Radio className="w-4 h-4"/>
              </div>
              <span>Ambient Radio</span>
            </li>
          </ul>
        </div>
      )}
    </div>
  );
};

export default Sidebar;